import numpy as np, itertools
def feats(w):
    return {"1":np.ones_like(t),"t":t,"P":P,"P2":P**2,"1/P":1/P,"tP":t*P,"t/P":t/P,"sin/P":np.sin(w*t)/P,"cos/P":np.cos(w*t)/P,"sin":np.sin(w*t),"cos":np.cos(w*t),"sinP":np.sin(w*t)*P,"cosP":np.cos(w*t)*P,"sqrtt":np.sqrt(t),"t2":t**2,"P/t":P/t}
best=[]
for w in np.arange(0.36,0.46,0.005):
    F=feats(w)
    keys=["1","t","P","P2","1/P","tP","t/P","sin/P","cos/P","sin","cos","sinP","cosP","sqrtt","t2","P/t"]
    for combo in itertools.combinations(keys,4):
        # need sin/cos pair when using sin-based
        A=np.column_stack([F[k] for k in combo])
        c,*_=np.linalg.lstsq(A,dP_dt,rcond=None)
        e=np.mean((A@c-dP_dt)**2)/np.var(dP_dt)
        best.append((e,round(w,3),combo,np.round(c,3)))
best.sort(key=lambda x:x[0])
